        group.MapPost("/{projectId:guid}/reopen", async (Guid projectId, HttpContext http, ProjectService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "projects.close.manage", null, ct, projectId), () => service.ReopenAsync(Tenant(http), Actor(http), projectId, ct)));
        group.MapPost("/{projectId:guid}/capital-handoffs", async (Guid projectId, CapitalHandoffRequest request, HttpContext http, ProjectService service, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessAsync(http, subjects, authorizer, "projects.capital.manage", null, ct, projectId), () => service.CreateCapitalHandoffAsync(Tenant(http), Actor(http), projectId, request, Correlation(http), ct), StatusCodes.Status202Accepted));
        return app;
    }

    private static async Task<Access?> AccessAsync(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, string permission, Guid? entityId, CancellationToken ct, Guid? projectId = null)
    {
        if (!Guid.TryParse(http.User.FindFirstValue("tenant_id"), out var tenantId) || !Guid.TryParse(http.User.FindFirstValue("membership_id"), out var membershipId) || !Guid.TryParse(http.User.FindFirstValue(ClaimTypes.NameIdentifier), out var actorId)) return null;
        var tenant = new TenantId(tenantId); var subject = await subjects.LoadAsync(tenant, membershipId, ct); if (subject is null) return null; if (entityId is not null && Guid.TryParse(http.User.FindFirstValue("legal_entity_id"), out var claimEntity) && claimEntity != entityId) return new(tenant, actorId, membershipId, false); var allowed = authorizer.Authorize(subject, permission, PermissionScope.ForTenant(tenant)); if (allowed && projectId is not null) allowed = await http.RequestServices.GetRequiredService<ProjectsRepository>().CanAccessProjectAsync(tenant, projectId.Value, actorId, membershipId, permission, ct); return new(tenant, actorId, membershipId, allowed);
    }
    private static async Task<IResult> Execute<T>(HttpContext http, Access? access, Func<Task<T>> action, int status = StatusCodes.Status200OK) { if (access is null) return Results.Unauthorized(); if (!access.Allowed) return Results.Forbid(); try { var result = await action(); return status == StatusCodes.Status201Created ? Results.Created(http.Request.Path, result) : status == StatusCodes.Status202Accepted ? Results.Accepted(http.Request.Path, result) : Results.Ok(result); } catch (ProjectException ex) { var code = ex.Code; var statusCode = code.Contains("not_found", StringComparison.Ordinal) ? 404 : code.Contains("conflict", StringComparison.Ordinal) || code.Contains("duplicate", StringComparison.Ordinal) ? 409 : 400; return Results.Problem(statusCode: statusCode, title: code, extensions: new Dictionary<string, object?> { ["code"] = code }); } }
    private static TenantId Tenant(HttpContext http) => new(Guid.Parse(http.User.FindFirstValue("tenant_id")!));
    private static Guid Actor(HttpContext http) => Guid.Parse(http.User.FindFirstValue(ClaimTypes.NameIdentifier)!);
    private static Guid Membership(HttpContext http) => Guid.Parse(http.User.FindFirstValue("membership_id")!);
    private static Guid Correlation(HttpContext http) => Guid.TryParse(http.Request.Headers["X-Correlation-Id"], out var value) ? value : Guid.CreateVersion7();
    private sealed record Access(TenantId Tenant, Guid ActorId, Guid MembershipId, bool Allowed);
}

